{
  "clusters": [
    {
      "label": "Local task",
      "members": [
        {"sample": 1, "id": "s1"},
        {"sample": 2, "id": "s1"}
      ],
      "text": "Choose the next cell for a computation budget using only a cell and its direct neighbors, with fairness and no permanent starvation."
    },
    {
      "label": "Cell state",
      "members": [
        {"sample": 1, "id": "s2"},
        {"sample": 2, "id": "s3"}
      ],
      "text": "Each cell has potential and resistance (and sample 2 adds age) for a local priority score."
    },
    {
      "label": "No global view",
      "members": [
        {"sample": 1, "id": "s3"},
        {"sample": 2, "id": "s5"}
      ],
      "text": "A local rule cannot see the global maximum, so it must rely only on the cell and its neighbors."
    },
    {
      "label": "Single token",
      "members": [
        {"sample": 1, "id": "s4"},
        {"sample": 2, "id": "s2"}
      ],
      "text": "Use one budget token that moves locally; the cell holding it receives the next budget."
    },
    {
      "label": "Fairness conclusion",
      "members": [
        {"sample": 1, "id": "s6"},
        {"sample": 2, "id": "s8"}
      ],
      "text": "On a connected graph, the local token process serves every cell infinitely often."
    }
  ],
  "divergent": [
    {
      "label": "Round-robin handoff",
      "samples": [1],
      "text": "Pass the token by local round-robin over neighbors, optionally biased by potential/resistance."
    },
    {
      "label": "Score handoff",
      "samples": [2],
      "text": "The token holder compares its score with direct neighbors and moves to the highest-scoring cell."
    },
    {
      "label": "Bias starvation check",
      "samples": [1],
      "text": "Potential/resistance bias alone may starve cells; round-robin or aging is needed for no-starvation."
    },
    {
      "label": "Age starvation proof",
      "samples": [2],
      "text": "A cell's age grows when unserved, raising its score until it outcompetes neighbors and draws the token."
    },
    {
      "label": "Connectedness pull",
      "samples": [2],
      "text": "Because the graph is connected, the rising age score pulls the token through boundary cells toward any starved region."
    },
    {
      "label": "Minimal mechanism",
      "samples": [1],
      "text": "The minimal mechanism is a local token with round-robin/biased handoff, assuming a connected graph."
    }
  ]
}
